// Auto-generated by ApexStudio: in-memory data layer for preview.
// Same surface as apexHttp.js, so the UI is identical in preview and export.
import { SCHEMA, SEED, WRITE_ROLES, DELETE_ROLES } from './apexData.js';

let _seq = 1;
const uid = (p) => (p || 'row') + '-' + (_seq++);

const db = {};
for (const name of Object.keys(SCHEMA)) {
  db[name] = (SEED[name] || []).map((r) => ({
    id: r.id || uid('seed'),
    created_at: r.created_at || new Date().toISOString(),
    ...r,
  }));
}

// Preview convenience: start signed in as an admin so CRUD works immediately.
// (The real backend never auto-authenticates.) Log out to test other roles.
const users = [{ id: 'u-1', email: 'admin@demo.app', password: 'admin', role: 'admin' }];
let current = { id: 'u-1', email: 'admin@demo.app', role: 'admin' };

const listeners = new Set();
const emit = (evt) => listeners.forEach((fn) => { try { fn(evt); } catch (e) {} });

function requireRole(roles) {
  if (!current) throw new Error('Not authenticated');
  if (roles && roles.indexOf(current.role) === -1) {
    throw new Error('Forbidden: requires role ' + roles.join(' or '));
  }
}
function coll(entity) {
  if (!db[entity]) throw new Error('Unknown entity: ' + entity);
  return db[entity];
}
const CONTROL = ['q', 'sort', 'order', 'limit', 'offset'];
function matches(row, params) {
  for (const k of Object.keys(params || {})) {
    if (CONTROL.indexOf(k) !== -1) continue;
    if (String(row[k]) !== String(params[k])) return false;
  }
  return true;
}

export const api = {
  async list(entity, params = {}) {
    let rows = coll(entity).filter((r) => matches(r, params));
    if (params.q) {
      const q = String(params.q).toLowerCase();
      rows = rows.filter((r) => Object.values(r).some((v) => String(v).toLowerCase().includes(q)));
    }
    if (params.sort) {
      const s = params.sort, dir = params.order === 'desc' ? -1 : 1;
      rows = [...rows].sort((a, b) => (a[s] > b[s] ? 1 : a[s] < b[s] ? -1 : 0) * dir);
    }
    const offset = +params.offset || 0;
    const limit = params.limit != null ? +params.limit : rows.length;
    return rows.slice(offset, offset + limit).map((r) => ({ ...r }));
  },
  async get(entity, id) {
    const r = coll(entity).find((x) => String(x.id) === String(id));
    if (!r) throw new Error('Not found');
    return { ...r };
  },
  async create(entity, data) {
    requireRole(WRITE_ROLES);
    const row = { id: uid(entity), created_at: new Date().toISOString(), ...data };
    coll(entity).push(row);
    emit({ type: 'change', entity, action: 'create', id: row.id });
    return { ...row };
  },
  async update(entity, id, data) {
    requireRole(WRITE_ROLES);
    const r = coll(entity).find((x) => String(x.id) === String(id));
    if (!r) throw new Error('Not found');
    Object.assign(r, data);
    emit({ type: 'change', entity, action: 'update', id });
    return { ...r };
  },
  async remove(entity, id) {
    requireRole(DELETE_ROLES);
    const c = coll(entity);
    const i = c.findIndex((x) => String(x.id) === String(id));
    if (i < 0) throw new Error('Not found');
    c.splice(i, 1);
    emit({ type: 'change', entity, action: 'delete', id });
    return { ok: true };
  },
};

export const auth = {
  async register({ email, password, role }) {
    if (users.find((u) => u.email === email)) throw new Error('Email already registered');
    // Self-registration can never grant an elevated role (matches the backend).
    const user = { id: 'u-' + (users.length + 1), email, role: 'viewer' };
    users.push({ ...user, password });
    current = user;
    return { token: 'mock-' + user.id, user };
  },
  async login({ email, password }) {
    const u = users.find((x) => x.email === email && x.password === password);
    if (!u) throw new Error('Invalid credentials');
    current = { id: u.id, email: u.email, role: u.role };
    return { token: 'mock-' + u.id, user: current };
  },
  async me() { return current; },
  async logout() { current = null; },
  async currentUser() { return current; },
};

export const files = {
  async upload(file) {
    const url = (typeof URL !== 'undefined' && URL.createObjectURL) ? URL.createObjectURL(file) : '';
    return { id: 'f-' + Date.now(), filename: (file && file.name) || 'file', url };
  },
};

export const events = {
  subscribe(cb) { listeners.add(cb); return () => listeners.delete(cb); },
};

const _subs = [];
export const ai = {
  async chat(messages, opts = {}) {
    const last = [...(messages || [])].reverse().find((m) => m.role === 'user');
    const text = last ? String(last.content) : '';
    return { reply: '[simulated AI] ' + (text.slice(0, 400) || 'Hello!'), simulated: true };
  },
};
export const integrations = {
  async call(name, payload = {}) {
    try {
      const res = await fetch('/api/integrations/' + name, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (res.ok) return await res.json();
    } catch (_) {}
    return { simulated: true, integration: name, echo: payload };
  },
};
export const payments = {
  async checkout({ plan, success_url } = {}) {
    const sub = { id: 'sub-' + (_subs.length + 1), plan, status: 'active', provider: 'simulated', created_at: new Date().toISOString() };
    _subs.push(sub);
    return { id: sub.id, url: success_url || '#', simulated: true };
  },
  async subscriptions() { return _subs.map((s) => ({ ...s })); },
};
